import TagList from "./TagList";
import { TAG_STATUS } from "./usePopularTags";

function TagListContent({ status, tags }) {
  if (status === TAG_STATUS.LOADING) {
    return <p>Loading tags...</p>;
  }

  if (tags.length > 0) {
    return <TagList tags={tags} />;
  }

  if (status === TAG_STATUS.ERROR) {
    return <p>Unable to load tags</p>;
  }

  return <p>Tags list not available</p>;
}

export default TagListContent;

const MAX_TAGS = 50;

function TagList({ tags }) {
  return tags.slice(0, MAX_TAGS).map((name) => (
    <button className="tag-pill tag-default" key={name}>
      {name}
    </button>
  ));
}

export default TagList;

import TagList from "./TagList";
import { TAG_MESSAGES } from "./constants";
import { TAG_STATUS } from "./usePopularTags";

function TagListContent({ status, tags }) {
  if (status === TAG_STATUS.LOADING) {
    return <p>{TAG_MESSAGES.loading}</p>;
  }

  if (tags.length > 0) {
    return <TagList tags={tags} />;
  }

  if (status === TAG_STATUS.ERROR) {
    return <p>{TAG_MESSAGES.error}</p>;
  }

  return <p>{TAG_MESSAGES.empty}</p>;
}

export default TagListContent;

import { MAX_VISIBLE_TAGS } from "./constants";

function TagList({ tags }) {
